import{_ as r,o as d,c as a,a2 as e}from"./chunks/framework.BXzK3EA4.js";const T=JSON.parse('{"title":"태합입지전 V / V DX: 게임 메커니즘 독립 참고서","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Ref-Taikou-Risshiden.md","filePath":"rules/Ref-Taikou-Risshiden.md"}'),n={name:"rules/Ref-Taikou-Risshiden.md"};function o(s,t,g,l,h,i){return d(),a("div",null,[...t[0]||(t[0]=[e('<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p></div><blockquote><p>출처 인계: <a href="https://github.com/islee23520/seoul-kenshi/blob/docs/reference-context-sync-st_01a079f1/.omo/research/README.md" target="_blank" rel="noreferrer">공유 조사 색인</a>. 로컬 sources.json·원문 패킷 언급은 조사 당시 기록이며 이 전달에 원시 자료가 포함된다는 뜻이 아니다. 누락된 ID는 미확인으로 남긴다. 자동 생성 문서입니다 — 원본은 저장소 내부 조사 문서(<code>taikou-risshiden.md</code>)에서 파생했으며 금지 용어는 위키 공개 기준에 맞게 치환했다.</p></blockquote><h1 id="태합입지전-v-v-dx-게임-메커니즘-독립-참고서" tabindex="-1">태합입지전 V / V DX: 게임 메커니즘 독립 참고서 <a class="header-anchor" href="#태합입지전-v-v-dx-게임-메커니즘-독립-참고서" aria-label="Permalink to &quot;태합입지전 V / V DX: 게임 메커니즘 독립 참고서&quot;">​</a></h1><blockquote><p><strong>대상과 판본:</strong> 《태합입지전 V》의 개인 생애·직업·세력 시스템을 다룬다. 원작 Windows판은 <strong>2004년 3월 12일</strong>, DX는 일본 기준 <strong>2022년 5월 19일</strong> 출시다. <strong>1999년 작품은 III이지 V가 아니다.</strong> Steam 영문 상점은 DX 출시일을 5월 18일로 표시하므로 지역별 표시를 구별한다. [문서][S-TR-K01][S-TR-O02]</p><p><strong>수치 적용 원칙:</strong> 공식 웹 매뉴얼은 <strong>2022 DX판</strong> 자료다. 아래에서 <code>DX 기준</code>인 수치를 2004 Windows 원작의 규칙으로 소급하지 않는다. 한국어 위키는 원작·PS2·PSP·DX를 함께 설명하므로 판본 차이가 명시된 것만 구분하며, 상충값은 그대로 밝힌다. **[문서]**는 열람한 자료의 명시적 주장이지 실행·코드 검증을 뜻하지 않는다. **[추론]**은 자료를 바탕으로 재구성한 구조·계산 예시다. **[미확인]**은 자료만으로 확정할 수 없는 사항이다. 출처는 말미와 공동 <code>sources.json</code>의 고유 ID로 찾을 수 있다.</p></blockquote><h2 id="_1-개요-—-역사-속-한-사람의-생애" tabindex="-1">1. 개요 — 역사 속 한 사람의 생애 <a class="header-anchor" href="#_1-개요-—-역사-속-한-사람의-생애" aria-label="Permalink to &quot;1. 개요 — 역사 속 한 사람의 생애&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>내용</th><th>근거</th></tr></thead><tbody><tr><td>개발·발매</td><td>원작 코에이, DX 코에이테크모게임스</td><td>[문서][S-TR-K01][S-TR-O02]</td></tr><tr><td>장르</td><td>역사 시뮬레이션과 RPG를 결합한 코에이의 ‘리코에이션 게임’. 국가지도만 운영하는 전략물이 아니라 한 인물의 취업·수련·교유·생활·출세를 조작한다</td><td>[문서][S-TR-O01][S-TR-M1200]</td></tr><tr><td>배경</td><td>16세기 일본 전국시대. 히데요시의 출세가 모티브지만 다른 인물과 직업도 선택 가능</td><td>[문서][S-TR-O01]</td></tr><tr><td>주요 판본</td><td>V: Windows, 이후 PS2·PSP 이식. DX: Windows/Steam·Nintendo Switch</td><td>[문서][S-TR-K01][S-TR-O01]</td></tr><tr><td>DX 규모</td><td>플레이 가능 인물 <strong>960명</strong>, 시나리오 <strong>9개</strong>, 이벤트 <strong>630개 이상</strong>, 엔딩 <strong>39종</strong>, 전투 스킬 <strong>160종 이상</strong>, 아이템 <strong>300점 이상</strong></td><td>[문서][S-TR-O03]</td></tr><tr><td>직업 체계</td><td>조직 소속 <strong>4계열</strong>: 무사·닌자·해적·상인. 구도 <strong>4계열</strong>: 검호·다인·의사·대장장이</td><td>[문서][S-TR-M1200]</td></tr><tr><td>중심 보상</td><td>현 생애의 공훈·직위·능력·특기와, 다음 생애의 선택지를 여는 주인공 카드가 병존</td><td>[문서][S-TR-M1200][S-TR-M3400]</td></tr></tbody></table><p><strong>순수 전략게임과의 차이:</strong> 국가의 성장과 플레이어의 성장이 일치하지 않는다. 말단 가신은 자신의 임무와 부대만 관리하다가 성주가 된 뒤에야 타인에게 임무를 배정한다. 상인은 성을 소유하지 않고도 다이묘의 전략에 영향력을 행사하고, 검호는 통일 없이 제자 <strong>20명</strong>으로 직업 엔딩을 볼 수 있다. 즉 플레이 단위는 ‘국가 하나’보다 <strong>역사적 세계 안의 개인과 그 개인에게 허용된 권한</strong>이다. [추론][S-TR-M5100][S-TR-M5130][S-TR-M4500][S-TR-M5500]</p><p><strong>주의할 비유:</strong> ‘농민 → 사무라이 → 다이묘 → 섭정’은 히데요시의 입지전적 이미지를 설명하는 말이지 모든 주인공에게 공통인 직업 트리가 아니다. 일반적인 시작 신분에는 낭인과 기존 직책이 있고, 무사의 최하위 직책은 아시가루 조장이다. 관백·쇼군·태정대신·태합은 같은 승진 사다리의 연속 단계가 아니다. [문서][S-TR-K01][S-TR-M4200][S-TR-M5160]</p><h2 id="_2-코어-루프-—-일-수련-인간관계-보고" tabindex="-1">2. 코어 루프 — 일, 수련, 인간관계, 보고 <a class="header-anchor" href="#_2-코어-루프-—-일-수련-인간관계-보고" aria-label="Permalink to &quot;2. 코어 루프 — 일, 수련, 인간관계, 보고&quot;">​</a></h2><h3 id="_2-1-조직-소속자의-반복" tabindex="-1">2.1 조직 소속자의 반복 <a class="header-anchor" href="#_2-1-조직-소속자의-반복" aria-label="Permalink to &quot;2.1 조직 소속자의 반복&quot;">​</a></h3><ol><li><strong>평정 참석:</strong> 상사가 정한 방침 아래 현재 신분으로 받을 수 있는 주명(主命)을 수령한다. 무사 평정은 홀수 달 <strong>1~5일</strong>이다. [문서][S-TR-M5100]</li><li><strong>준비:</strong> 필요한 기술, 물품, 자금, 체력을 확인한다. 말 구매라면 도시별 말 시세를, 수련이라면 자신보다 높은 기능을 가진 스승을 찾는다. [문서][S-TR-M3200][S-TR-M3300]</li><li><strong>여행과 수행:</strong> 실제 목적지로 이동해 구매·교섭·개발·훈련·공작·전투를 수행한다. 일부 작업의 미니게임 성적이 경험치나 실적을 바꾼다. [문서][S-TR-M1200]</li><li><strong>귀환과 보고:</strong> 물건을 구하거나 작업을 끝낸 것만으로 완료되지 않는다. <strong>기한 안에 상사에게 보고</strong>해야 실적에 따른 공훈을 받는다. [문서][S-TR-M5100]</li><li><strong>남는 시간의 개인 활동:</strong> 교역으로 생활비 확보 → 차·선물·대련으로 친밀도 확보 → 사사와 비기 습득 → 다음 임무의 실적 향상. [문서][S-TR-M5100]</li><li><strong>승진:</strong> 누적 공훈이 기준을 넘으면 평정에서 신분이 올라간다. 성주급부터는 임무 수령자가 임무 배분자로 바뀐다. [문서][S-TR-M1200][S-TR-M5130]</li></ol><p><strong>일정 예시:</strong> 남은 기한이 20일, 왕복 이동이 8일, 작업이 6일, 회복이 2일이라면 자유시간은 <code>20 - 8 - 6 - 2 = 4일</code>이다. 이 숫자는 설명용이며 해당 임무의 고정 소요일수가 아니다. 핵심은 <strong>귀환일을 작업 시간과 별도로 예약</strong>하는 것이다. [추론][S-TR-M5100]</p><h3 id="_2-2-독립·구도-직업의-반복" tabindex="-1">2.2 독립·구도 직업의 반복 <a class="header-anchor" href="#_2-2-독립·구도-직업의-반복" aria-label="Permalink to &quot;2.2 독립·구도 직업의 반복&quot;">​</a></h3><ul><li><strong>검호:</strong> 스승과 교유 → 입문 → 대련·비기 전수 → 인가 취득 → 제자 모집·도장 운영·대회. [문서][S-TR-M5500]</li><li><strong>다인:</strong> 다기 확보 → 다도 수련 → 다석 횟수 축적 → 다선 칭호 → 다실 → 손님 <strong>2명</strong>의 관계 개선·다기 제작. [문서][S-TR-M5600]</li><li><strong>의사:</strong> 사사 → 진료·채집·제조 카드 → 약초 → 생약 → 조합 → 진단·처방·진료비 선택 → 의사 평판. [문서][S-TR-M5700]</li><li><strong>대장장이:</strong> 대장간 하급 작업 → 제작법 습득 → 사철·땔감 확보 → 철 생산 → 무구 제작 → 품질·칭호·헌상 목표. [문서][S-TR-M5800][S-TR-K01]</li></ul><p>구도 활동은 조직 직업과 병행할 수 있지만, 자택 작업장은 <strong>동시에 1개</strong>만 건설할 수 있다. 또한 공식 매뉴얼은 도장 개설에 <strong>낭인 신분과 1,000관</strong>을 요구한다. ‘부직업이므로 어떤 신분에서 모든 시설을 동시에 운영한다’는 해석은 틀리다. [문서][S-TR-M1200][S-TR-M5500]</p><h2 id="_3-진행-구조-—-직위가-명령의-범위를-바꾼다" tabindex="-1">3. 진행 구조 — 직위가 명령의 범위를 바꾼다 <a class="header-anchor" href="#_3-진행-구조-—-직위가-명령의-범위를-바꾼다" aria-label="Permalink to &quot;3. 진행 구조 — 직위가 명령의 범위를 바꾼다&quot;">​</a></h2><h3 id="_3-1-무사-승진표-dx-공식값" tabindex="-1">3.1 무사 승진표: DX 공식값 <a class="header-anchor" href="#_3-1-무사-승진표-dx-공식값" aria-label="Permalink to &quot;3.1 무사 승진표: DX 공식값&quot;">​</a></h3><p>공훈은 아래 단계의 <strong>누적 기준</strong>이며 승진 때마다 전액 지불하는 화폐가 아니다. 월급은 매월 <strong>1일 자택 금고</strong>로 들어간다. [문서][S-TR-M4200]</p><table tabindex="0"><thead><tr><th>신분</th><th style="text-align:right;">누적 무사 공훈</th><th style="text-align:right;">월 수입</th><th style="text-align:right;">최대 지휘 병사</th><th>핵심 권한·제약</th></tr></thead><tbody><tr><td>아시가루 조장(足軽組頭)</td><td style="text-align:right;">0</td><td style="text-align:right;">5관</td><td style="text-align:right;">1,500</td><td>기본 임무·수련</td></tr><tr><td>아시가루 대장(足軽大将)</td><td style="text-align:right;">200</td><td style="text-align:right;">10관</td><td style="text-align:right;">2,000</td><td>배신(陪臣), 즉 자신의 가신을 보유 가능</td></tr><tr><td>사무라이 대장(侍大将)</td><td style="text-align:right;">600</td><td style="text-align:right;">20관</td><td style="text-align:right;">2,500</td><td>수령 가능한 임무 증가</td></tr><tr><td>부장(部将)</td><td style="text-align:right;">1,400</td><td style="text-align:right;">50관</td><td style="text-align:right;">3,000</td><td>외교 임무 등; 자신이 배신이면 최고 직위</td></tr><tr><td>가로(家老)</td><td style="text-align:right;">3,000</td><td style="text-align:right;">100관</td><td style="text-align:right;">4,000</td><td>일반 직신 최고위; 성주 임명 후보</td></tr><tr><td>성주(城主)</td><td style="text-align:right;">임명</td><td style="text-align:right;">지배 성 월수입의 1/100</td><td style="text-align:right;">4,000</td><td>1개 성의 평정·인사·군단 편성</td></tr><tr><td>국주(国主)</td><td style="text-align:right;">임명</td><td style="text-align:right;">지배 성 월수입의 1/100</td><td style="text-align:right;">4,000</td><td>복수 성 지배·성 사이 물자 운송</td></tr></tbody></table><p>표 전체: [문서][S-TR-M4200]. 따라서 공훈 600에서 부장 기준까지의 차이는 <code>1,400 - 600 = 800</code>이다. [추론][S-TR-M4200]</p><p><strong>임명은 별도 조건:</strong> 한국어 위키는 플레이어 성주 임명의 공훈을 <strong>4,500</strong>, 국주를 <strong>10,000</strong>으로 설명하며, 성주에는 주군 세력의 <strong>3개국 이상 진출</strong> 등의 제약도 설명한다. 공식 매뉴얼은 가로 중 임명된다고만 한다. 이 수치들은 <strong>커뮤니티가 보고한 플레이어 조건</strong>이며 모든 NPC 임명에 공통인 필요충분조건으로 쓰지 않는다. [문서][S-TR-K01][S-TR-M5130]</p><h3 id="_3-2-다이묘와-조정-관위는-별도의-상승-축" tabindex="-1">3.2 다이묘와 조정 관위는 별도의 상승 축 <a class="header-anchor" href="#_3-2-다이묘와-조정-관위는-별도의-상승-축" aria-label="Permalink to &quot;3.2 다이묘와 조정 관위는 별도의 상승 축&quot;">​</a></h3><ul><li>성주·국주가 <strong>모반</strong>하면 독립 다이묘가 될 수 있다. 원래 주군과 관계가 최악으로 바뀌므로 군비가 필요하다. 주군 사망 후 조건을 만족하여 후계자가 되는 경로도 있다. 단순히 공훈을 계속 쌓으면 자동으로 다이묘가 되는 구조가 아니다. [문서][S-TR-M5160]</li><li>다이묘는 공가에 조언을 부탁하고 조정에 헌금하여 관위를 올린다. 관위는 <strong>정6위하 → … → 정1위</strong>, 한 번에 <strong>1단계</strong>만 상승하며 지배 성 수 등 실력도 요구된다. [문서][S-TR-M5160]</li><li>한국어 위키의 통일 후 정권 구분은 겐지 계통의 정이대장군·막부, 후지와라 계통의 관백, 그 밖의 태정대신, 히데요시의 태합 등을 설명한다. <strong>‘regent’를 모든 캐릭터의 최종 직책으로 고정하지 않는다.</strong> 관위·씨족·개별 이벤트의 전체 판정표는 이번 조사에서 코드 수준으로 확인하지 않았다. [문서][미확인][S-TR-K01]</li></ul><h3 id="_3-3-다른-조직의-계급과-정상-목표" tabindex="-1">3.3 다른 조직의 계급과 정상 목표 <a class="header-anchor" href="#_3-3-다른-조직의-계급과-정상-목표" aria-label="Permalink to &quot;3.3 다른 조직의 계급과 정상 목표&quot;">​</a></h3><table tabindex="0"><thead><tr><th>직업</th><th>하급 → 중급 → 상급 → 거점장 → 수장</th><th>DX 하급 3단계 공훈 / 월급</th><th>천하제일의 대표 목표</th></tr></thead><tbody><tr><td>닌자</td><td>하닌 → 중닌 → 상닌 → 모토지메(元締) → 두목</td><td>0/10관, 300/50관, 1,500/100관</td><td><strong>12개</strong> 닌자 마을 제패, 또는 모든 지역 인술 습득, 또는 지지 다이묘 통일</td></tr><tr><td>해적</td><td>수부 → 수부두 → 선두 → 선대장 → 두령</td><td>0/10관, 300/50관, 1,500/100관</td><td><strong>16개 해역</strong> 제패, 또는 지지 다이묘 통일</td></tr><tr><td>상인</td><td>견습 → 테다이(手代) → 반토(番頭) → 지배인 → 당주</td><td>0/10관, 300/50관, 1,500/100관</td><td><strong>15개 상업권</strong>의 상인사, 모든 다이묘의 어용상인, 또는 지지 다이묘 통일</td></tr></tbody></table><p>표 전체: [문서][S-TR-M4300][S-TR-M4400][S-TR-M4500]. 한국어 위키의 중닌·수부두·테다이 <strong>500</strong> 표기와 상업권 <strong>16개</strong> 표기는 DX 공식값과 충돌한다. 실제 패치별 차이인지 위키 오류인지는 <strong>미확인</strong>이며, 이 문서의 DX 표는 공식값을 따른다. [미확인][S-TR-K01]</p><p>거점장은 공훈 임계만이 아니라 임명을 받아야 한다. 닌자·해적 거점장은 독립할 수 있고 해적은 조건에 따라 두령 축출도 가능하다. 상인 지배인은 실적을 쌓아 노렌와케(분가·독립)를 허락받는다. [문서][S-TR-M5200][S-TR-M5300][S-TR-M5400]</p><h3 id="_3-4-초반·중반·후반의-실제-변화" tabindex="-1">3.4 초반·중반·후반의 실제 변화 <a class="header-anchor" href="#_3-4-초반·중반·후반의-실제-변화" aria-label="Permalink to &quot;3.4 초반·중반·후반의 실제 변화&quot;">​</a></h3><table tabindex="0"><thead><tr><th>구간</th><th>주된 부족분</th><th>플레이 변화</th></tr></thead><tbody><tr><td>초반</td><td>돈·스승·기능·약한 장비</td><td>낮은 위험의 주명, 차와 선물, 교역, 치료·수련 기반 확보</td></tr><tr><td>중반</td><td>임명 조건·좋은 부하·전문 카드</td><td>성주급 또는 지배인 진입, 직접 실행과 위임의 분담, 소속에 묶인 비기 확보</td></tr><tr><td>후반</td><td>외교·세계 상태·수명·엔딩 조건</td><td>전국 지배 또는 직업 목표 달성, 숙련 스승의 사망과 역사 분기 관리</td></tr></tbody></table><p>위 구분은 고정 레벨대가 아닌 시스템 변화의 재구성이다. 이미 다이묘인 인물을 선택하면 조직 지휘 단계에서 시작할 수 있다. [추론][S-TR-M1200][S-TR-M5130][S-TR-K01]</p><h2 id="_4-경제-—-개인-지갑-거점-재정-교역망의-분리" tabindex="-1">4. 경제 — 개인 지갑, 거점 재정, 교역망의 분리 <a class="header-anchor" href="#_4-경제-—-개인-지갑-거점-재정-교역망의-분리" aria-label="Permalink to &quot;4. 경제 — 개인 지갑, 거점 재정, 교역망의 분리&quot;">​</a></h2><h3 id="_4-1-자원과-흐름" tabindex="-1">4.1 자원과 흐름 <a class="header-anchor" href="#_4-1-자원과-흐름" aria-label="Permalink to &quot;4.1 자원과 흐름&quot;">​</a></h3><table tabindex="0"><thead><tr><th>자원</th><th>획득</th><th>소모·역할</th><th>근거</th></tr></thead><tbody><tr><td>개인 소지금·금고</td><td>봉록, 교역, 의뢰 보수, 물품 매각, 도박</td><td>숙박, 수련, 선물, 무구·다기·약, 용심봉</td><td>[문서][S-TR-M3200][S-TR-M4200]</td></tr><tr><td>군자금·점포 자금</td><td>거점 수입, 군자금 조달, 광산, 판로</td><td>부하의 주명 비용, 군비, 외교, 연말 상납</td><td>[문서][S-TR-M5130][S-TR-M5400]</td></tr><tr><td>군량</td><td>쌀가게에서 매입, 거점 보유·수송</td><td>원정 유지; 고갈되면 사기 급감</td><td>[문서][S-TR-M3200][S-TR-M3600]</td></tr><tr><td>군마·철포·대통</td><td>말집·대장간·남만상관</td><td>병종 편성; 말·철포는 해당 병사와 1:1</td><td>[문서][S-TR-M3200][S-TR-M3600]</td></tr><tr><td>배</td><td>선박 건조</td><td>해군 병력·상위 함선·해외무역</td><td>[문서][S-TR-K01][S-TR-M3600]</td></tr><tr><td>교역품</td><td>도시별 교역소 구매·투자·판로 가공</td><td>차익 거래, 임무 납품, 제작 재료</td><td>[문서][S-TR-M4500][S-TR-K03]</td></tr><tr><td>약초·사철</td><td>지도상 채집, 해당 카드 필요</td><td>생약·약 제조, 제철</td><td>[문서][S-TR-M5700][S-TR-M5800]</td></tr><tr><td>귀중품</td><td>상가 구매·제작·이벤트</td><td>장비, 능력 보정, 선물, 수련 자격, 해외 교역 문서</td><td>[문서][S-TR-M3200][S-TR-K01]</td></tr></tbody></table><p>통화의 커뮤니티 표기는 <strong>1관 = 1,000문</strong>이다. 개인 지갑에 현금이 많다고 주군의 군자금이나 성의 군마가 자동 증가하는 것은 아니므로 두 층의 재정을 구별한다. [문서][S-TR-K01]; [추론][S-TR-M3200][S-TR-M5130]</p><h3 id="_4-2-교역과-적재량" tabindex="-1">4.2 교역과 적재량 <a class="header-anchor" href="#_4-2-교역과-적재량" aria-label="Permalink to &quot;4.2 교역과 적재량&quot;">​</a></h3><ul><li>도시마다 상품과 가격이 다르다. 쌀은 일반 교역품 목록이 아니라 쌀가게의 <strong>군량</strong>으로 거래한다. [문서][S-TR-M3200][S-TR-K03]</li><li>상인의 DX 적재량은 견습 <strong>30,000</strong>, 테다이 <strong>40,000</strong>, 반토 <strong>50,000</strong>, 지배인 <strong>60,000</strong>이다. 이는 물건 <strong>개수</strong>가 아니라 적재 단위다. 한국어 위키는 일반 비상인 한도 <strong>6,000</strong>, 비상인 거래 수수료 **20%**를 설명한다. 수수료 적용 방향·반올림·예외의 전체 공식은 미확인이다. [문서][S-TR-M4500][S-TR-K01]</li><li>상품별 무게가 다르므로 <code>Σ(상품 수량 × 상품 중량) ≤ 적재 한도</code>로 읽는다. 가다랑어 중량 <strong>60</strong>을 사용한 예에서는 6,000이면 <strong>100개</strong>, 30,000이면 <strong>500개</strong>를 실을 수 있다. 재고와 자금이 충분하다는 가정이다. [추론][S-TR-M4500][S-TR-K01][S-TR-K03]</li><li>순익의 회계적 정의는 <code>매각대금 - 매입대금 - 수수료 - 호위·숙박 등 직접비</code>다. 가령 매입 500관, 매각 900관, 부대비용 50관이면 순익 <strong>350관</strong>이다. 이는 시세 엔진 공식이나 보장 교역 루트가 아니다. [추론][S-TR-M3200][S-TR-M4500]</li></ul><h3 id="_4-3-상인-고유의-조직-경제" tabindex="-1">4.3 상인 고유의 조직 경제 <a class="header-anchor" href="#_4-3-상인-고유의-조직-경제" aria-label="Permalink to &quot;4.3 상인 고유의 조직 경제&quot;">​</a></h3><ul><li>지배인은 판로 <strong>1개</strong>, 당주는 <strong>5 + 지점 수</strong>만큼 개설할 수 있다. 판로 수입은 월초에 보고된다. 매장 있는 상업권에 속한 도시를 기반으로 개설한다. [문서][S-TR-M4500]</li><li>판로로 연결한 두 도시의 상품 조합이 가공품을 해금한다. 예: <strong>생사 + 염료 → 견직물</strong>, <strong>종이 + 기름 → 기름종이</strong>, <strong>기름종이 + 목재 → 우산</strong>. 마지막 예는 가공품을 다시 쓰는 3차 생산 사슬이다. 원료를 재고에서 1:1로 소비하는 제작 공식이라고 단정하지 않는다. [문서][S-TR-K03]</li><li>투자로 도시 규모를 올려 새 특산품을 만든다. 예: 오사후네 규모 <strong>12</strong>에서 비젠야키, 오미나토 규모 <strong>17</strong>에서 닭새우, 부산 규모 <strong>12</strong>에서 백자. [문서][S-TR-K03]</li><li>상인사는 상업권의 특권 상인 지위다. 상인사 쟁탈은 <strong>1개월 동안 담당 도시를 가장 많이 발전시키는 경쟁</strong>이다. 축제·학교·사찰·대다회·시장 활성화 등 도시 조건에 맞는 방식을 고르며 경쟁자 작업에 방해공작을 할 수도 있다. [문서][S-TR-M4500]</li><li>지배인은 연말에 본점으로 <strong>최소 5,000관</strong>을 상납한다. 높은 자율성 대신 정기적인 실적 의무가 남는다. [문서][S-TR-M5400]</li><li>교역품의 필수품 공급은 성의 주민안정도와 연결된다. 한국어 자료의 필수품 <strong>7종</strong>은 된장·간장·식초·소금·기름·목재·땔감이다. 부족 시 안정도 하락은 서술되지만 월별 하락량은 미확인이다. [문서][미확인][S-TR-K03]</li></ul><h3 id="_4-4-도박과-경제적-손실" tabindex="-1">4.4 도박과 경제적 손실 <a class="header-anchor" href="#_4-4-도박과-경제적-손실" aria-label="Permalink to &quot;4.4 도박과 경제적 손실&quot;">​</a></h3><p>공식 매뉴얼은 오이초카부·친치로린·조건부 핀코로의 <strong>3종</strong>을 소개한다. 한국어 자료의 기존 도박 환전율은 **80%**이므로 손익분기 칩 수는 <code>처음 칩 / 0.8 = 처음의 1.25배</code>다. 이는 무한 수익 수단이 아니며 패배·갈취와 시간 소모가 있다. 쌀 매매로 시세를 조작하는 반복 이익은 커뮤니티에서 허점을 이용한 플레이로 설명되므로 정상 시세 공식으로 채택하지 않는다. [문서][S-TR-M3200][S-TR-K01]; [추론][S-TR-K01]</p><h2 id="_5-캐릭터-파티-—-능력-실습-스승-사회적-지위" tabindex="-1">5. 캐릭터/파티 — 능력, 실습, 스승, 사회적 지위 <a class="header-anchor" href="#_5-캐릭터-파티-—-능력-실습-스승-사회적-지위" aria-label="Permalink to &quot;5. 캐릭터/파티 — 능력, 실습, 스승, 사회적 지위&quot;">​</a></h2><h3 id="_5-1-능력-5종과-기능-16종" tabindex="-1">5.1 능력 5종과 기능 16종 <a class="header-anchor" href="#_5-1-능력-5종과-기능-16종" aria-label="Permalink to &quot;5.1 능력 5종과 기능 16종&quot;">​</a></h3><table tabindex="0"><thead><tr><th>능력</th><th>직접 영향</th><th>수련에 유리한 예</th></tr></thead><tbody><tr><td>통솔(統率)</td><td>합전 공격·방어</td><td>아시가루·수군·군학</td></tr><tr><td>무력(武力)</td><td>개인전 공격·방어·이동 범위</td><td>무예·궁술·인술</td></tr><tr><td>정무(政務)</td><td>내정 주명의 성과</td><td>개간·광산·건축·산술</td></tr><tr><td>지모(知謀)</td><td>외교·내정 성과</td><td>군학·변설·의술</td></tr><tr><td>매력(魅力)</td><td>외교·권유 성과</td><td>예법·다도·의술</td></tr></tbody></table><p>표 전체: [문서][S-TR-M3300]. 능력과 기능은 별도 값이다. 가치 <strong>5 이상</strong> 귀중품 중 일부가 능력을 높이며, 성주·모토지메·선대장·지배인 이상이면 자택의 <strong>능력단련</strong>으로 기본 능력을 조금씩 높일 수 있다. 단련의 일별 증가량·능력 상한은 이번 자료에서 미확인이다. [문서][미확인][S-TR-M3300]</p><table tabindex="0"><thead><tr><th>기능</th><th>주요 용도</th><th>대표 수련처</th></tr></thead><tbody><tr><td>아시가루</td><td>보병 지휘</td><td>기능 높은 인물의 집</td></tr><tr><td>기마</td><td>기병 지휘</td><td>말집</td></tr><tr><td>철포</td><td>철포 부대·개인 화승총</td><td>대장간</td></tr><tr><td>수군</td><td>함선 지휘</td><td>해적 요새 수련장</td></tr><tr><td>궁술</td><td>활 사격·개인 활</td><td>기능 높은 인물의 집</td></tr><tr><td>무예</td><td>도검·창 개인전</td><td>도장</td></tr><tr><td>군학</td><td>합전·초기 특기 자원</td><td>기능 높은 인물의 집</td></tr><tr><td>인술</td><td>닌자 병종·쿠나이·사슬낫·공작</td><td>닌자 마을 수련장</td></tr><tr><td>건축</td><td>보수·증축·선박 공사</td><td>기능 높은 인물의 집</td></tr><tr><td>개간</td><td>신전 개발</td><td>남만사</td></tr><tr><td>광산</td><td>광산 개발</td><td>기능 높은 인물의 집</td></tr><tr><td>산술</td><td>가격 교섭</td><td>상가·기능 높은 인물</td></tr><tr><td>예법</td><td>외교</td><td>절; 일반 일본 서적 필요</td></tr><tr><td>변설</td><td>외교·가격 교섭</td><td>기능 높은 인물의 집</td></tr><tr><td>다도</td><td>다석의 효과</td><td>다인의 집; 다기 필요</td></tr><tr><td>의술</td><td>질병 저항·회복</td><td>의사의 집</td></tr></tbody></table><p>표 전체: [문서][S-TR-M3300][S-TR-M3200]. 가정집에서 사사 가능한 스승은 일반적으로 <strong>동일 세력·동맹 세력·낭인 중 자신보다 해당 기능이 높은 사람</strong>이다. 친밀도가 낮으면 거절당한다. 단순히 돈만 내면 아무 적장에게 모든 기능을 배울 수 있는 것은 아니다. [문서][S-TR-M3300][S-TR-M5100]</p><h3 id="_5-2-사용하면-성장한다-의-정확한-의미" tabindex="-1">5.2 ‘사용하면 성장한다’의 정확한 의미 <a class="header-anchor" href="#_5-2-사용하면-성장한다-의-정확한-의미" aria-label="Permalink to &quot;5.2 ‘사용하면 성장한다’의 정확한 의미&quot;">​</a></h3><ol><li><strong>기능 사사 경험:</strong> 방문 → 사사 → 미니게임/모의전 → 성과에 따른 경험치 → 기능 상승. 공식 매뉴얼의 일반 사사 한도는 <strong>레벨 4</strong>다. 무예 사사와 대련은 관계와 무예 수련을 함께 진전시킬 수 있다. [문서][S-TR-M1200][S-TR-M3300][S-TR-M5500]</li><li><strong>실무 누적과 칭호:</strong> 내정·외교·합전·다석·제작·진료의 실적 카운터가 별도 칭호 조건을 만족시킨다. 이것을 16개 기능 경험치와 같은 하나의 XP로 취급하면 안 된다. [문서][S-TR-K02]</li><li><strong>콘솔/DX 숙달자:</strong> 한국어 카드 표는 레벨 <strong>4 이후 경험치 100</strong>을 추가하면 **5(별)**에 도달하며 기능별 숙달자 칭호를 얻는다고 설명한다. 공식의 ‘사사로 4까지’와 구별되는 고숙련 층이다. 행동별 XP 배분의 상세 근거 링크는 접근 차단되어 검증하지 못했으므로 ‘구매 1번당 산술 +X’ 같은 값을 만들지 않는다. [문서][S-TR-K02]; [미확인][S-TR-X01]</li><li><strong>전수·소속으로 여는 기술:</strong> 같은 기능 레벨이라도 스승·유파·소속에 따라 습득 카드가 다르다. 닌자 마을별 독점 인술은 외부인 수련만으로 전부 얻을 수 없다. [문서][S-TR-M3500][S-TR-M5200][S-TR-K01]</li></ol><p><strong>실무 성장의 수치 예:</strong> 내정 경험 <strong>25/50/100/200</strong>은 능리/명봉행/명재상/현후와 정무 보정 <strong>+3/+6/+10/+15</strong>에 대응한다. 합전 <strong>5/10/25/50승</strong>은 책사/군사/지장/군신과 통솔 <strong>+3/+6/+10/+15</strong>에 대응한다. 같은 계열 칭호의 보정치를 모두 더해 <strong>+34</strong>라고 계산하지 않는다; 중첩 적용의 내부 규칙은 별도 확인 대상이다. [문서][S-TR-K02]; [미확인][S-TR-K02]</p><table tabindex="0"><thead><tr><th>도검 칭호</th><th>한국어 카드 표의 조건</th><th style="text-align:right;">무력 보정</th></tr></thead><tbody><tr><td>검사</td><td>도검 개인전 10승</td><td style="text-align:right;">+3</td></tr><tr><td>검객</td><td>도검 20승 + 무예 3 상대 승리</td><td style="text-align:right;">+6</td></tr><tr><td>검호</td><td>도검 50승 + 무예 4 상대 승리</td><td style="text-align:right;">+10</td></tr><tr><td>검성</td><td>도검 100승 + 무예 4 상대 승리, 또는 도검 천람대회 우승</td><td style="text-align:right;">+15</td></tr></tbody></table><p>표 전체: [문서][S-TR-K02]. <strong>전투 사용 → 전적 축적 → 칭호 → 능력 보정</strong>은 확인되지만, 전적과 무예 레벨업은 서로 바꿔 쓸 수 없다. [추론][S-TR-K02][S-TR-M3300]</p><h3 id="_5-3-인간관계·명성·결혼" tabindex="-1">5.3 인간관계·명성·결혼 <a class="header-anchor" href="#_5-3-인간관계·명성·결혼" aria-label="Permalink to &quot;5.3 인간관계·명성·결혼&quot;">​</a></h3><ul><li><strong>친밀도:</strong> 개별 인물과의 관계. 취향에 맞는 선물이 효과적이며 다기가 있으면 다석을 열 수 있다. 같은 상대에 대한 선물과 다석은 각각 <strong>월 1회</strong>, 대련은 반복 가능하다. 관계는 사사·취업·등용·카드 획득의 접근 조건이다. [문서][S-TR-M3200][S-TR-M3400][S-TR-M5100]</li><li><strong>명성·악명:</strong> 서로 다른 사회적 평가. 명분 없는 침공과 약탈·살해 등은 악명을 올리고, 큰 시주는 악명을 낮출 수 있다. 악명 수치와 ‘주군 살해자’ 같은 악명 <strong>카드 보유</strong>도 별개다. [문서][S-TR-M3600][S-TR-M3200][S-TR-K02]</li><li><strong>다실의 중재:</strong> 최대 <strong>2명</strong>을 초대하면 그 두 NPC의 상호 친밀도가 올라간다. 주인공과 NPC의 관계만 관리하는 시스템이 아니다. [문서][S-TR-M5600]</li><li><strong>라이벌:</strong> 특정 추천 인물에는 고정 라이벌이 있으며 히데요시-삿사 나리마사, 한조-이시카와 고에몽이 예다. 평정 진언과 일상 대화에 개입한다. 일반 라이벌 선정의 확률·우선순위는 미확인이다. [문서][미확인][S-TR-K01]</li><li><strong>결혼:</strong> 미혼 주인공은 대상과 교유하고 구혼 이벤트를 진행한다. 여관 여성·특정 여성 NPC·일부 여성 무장 등이 대상이며 이미 배우자가 있으면 통상 재혼할 수 없다. 배우자의 숨은 애정치는 한국어 자료상 <strong>0~100</strong>이고 대화·선물·추억의 장소 방문 등이 관계를 바꾼다. 식사·개인 이벤트 이점은 있으나 <strong>육아·후대 왕조 경영 시스템은 없다.</strong> 판본별 후보와 특수 이혼 이벤트는 구별한다. [문서][S-TR-K01]</li></ul><h3 id="_5-4-동료-가신-부상과-죽음" tabindex="-1">5.4 동료, 가신, 부상과 죽음 <a class="header-anchor" href="#_5-4-동료-가신-부상과-죽음" aria-label="Permalink to &quot;5.4 동료, 가신, 부상과 죽음&quot;">​</a></h3><p>일반 RPG의 고정 4인 파티 대신 <strong>인적 네트워크·배신·가신단·임시 호위</strong>가 존재한다. 아시가루 대장부터 낭인을 자신의 배신으로 모집할 수 있지만 급료를 자기 봉록에서 나눠주므로 낮은 직위일수록 보유 인원이 제한된다. 공식은 고정 동료 슬롯보다 이 급료 제약을 설명한다. [문서][S-TR-M5100][S-TR-M3200]</p><p>개인전의 아군은 용심봉·호위 대상 등이 될 수 있다. 합전에서는 군단장 <strong>1명 + 부대장 최대 4명</strong>의 지휘망으로 바뀐다. 호위 대상이 쓰러지는 것도 개인전 패배 조건이다. [문서][S-TR-M3500][S-TR-M3600]</p><p>일상 체력은 최소 <strong>1</strong>까지 내려가고 낮을수록 병에 걸리기 쉽다. 질병 중에는 <strong>능력 절반, 기능 레벨 -1</strong>, 수련 제한이 발생한다. 그러나 개인전 체력 소진은 해당 싸움의 패배이고 항상 사망은 아니다. 도적에게 패배하면 현금·교역품 전부를 빼앗길 수 있으며, 수명 종료·처형·특정 치명적 이벤트는 생애를 끝낼 수 있다. 병력 0, 부대장 사망, 주인공 사망을 하나로 취급하지 않는다. [문서][S-TR-M3100][S-TR-M3300][S-TR-M1200][S-TR-M3600][S-TR-K01]</p><h3 id="_5-5-카드-시스템-수집-기록과-현-생애의-능력을-분리" tabindex="-1">5.5 카드 시스템: 수집 기록과 현 생애의 능력을 분리 <a class="header-anchor" href="#_5-5-카드-시스템-수집-기록과-현-생애의-능력을-분리" aria-label="Permalink to &quot;5.5 카드 시스템: 수집 기록과 현 생애의 능력을 분리&quot;">​</a></h3><table tabindex="0"><thead><tr><th>카드 종류</th><th>획득과 작동</th></tr></thead><tbody><tr><td>주인공 카드</td><td>인물과 친해지거나 고유 조건을 만족. <strong>새 게임에서 해당 인물을 선택</strong>할 수 있게 함</td></tr><tr><td>비기 카드</td><td>유파·명상·인술 수련. 개인전에서 무기 조건과 기합 비용을 만족해야 사용</td></tr><tr><td>칭호 카드</td><td>전적·제작·직업 실적 등. 능력 보정과 시설·이벤트 조건</td></tr><tr><td>합전 카드</td><td>기능 수련 등. 병과·전장·지휘권 조건과 자원을 충족하면 사용</td></tr><tr><td>명소 카드</td><td>실제 장소 방문. 산·폭포·호수·사찰·절경의 <strong>5종</strong></td></tr><tr><td>기타 카드</td><td>대화·수련·이벤트에서 생활·제작·이동·교섭 수단 해금</td></tr></tbody></table><p>표 전체: [문서][S-TR-M3400]. 이는 덱에서 무작위로 손패를 뽑고 카드를 버리는 카드전투가 아니라, <strong>획득한 자격·명령·인물 선택권의 도감</strong>이다. [추론][S-TR-M3400][S-TR-M3500]</p><p>새 카드는 <strong>세이브할 때</strong> 전체 카드 목록에 등록된다. 주인공 카드 이외의 카드는 원칙적으로 획득한 생애에서만 유효하며, 조건부 인계 기능은 별도다. ‘이전 회차에서 검성을 얻었으니 모든 다음 캐릭터가 검성’이 아니다. 한국어 자료의 초기 추천 캐릭터는 히데요시·한조·요시타카·스케자에몬·무네요시 <strong>5명</strong>이며, 일반 친밀도 외에 대련·선물·퀴즈·칭호·역사 이벤트가 필요한 주인공 카드도 있다. [문서][S-TR-M3400][S-TR-K01]</p><h2 id="_6-전투-—-개인전과-합전은-다른-규칙이다" tabindex="-1">6. 전투 — 개인전과 합전은 다른 규칙이다 <a class="header-anchor" href="#_6-전투-—-개인전과-합전은-다른-규칙이다" aria-label="Permalink to &quot;6. 전투 — 개인전과 합전은 다른 규칙이다&quot;">​</a></h2><h3 id="_6-1-개인전의-명령과-판정" tabindex="-1">6.1 개인전의 명령과 판정 <a class="header-anchor" href="#_6-1-개인전의-명령과-판정" aria-label="Permalink to &quot;6.1 개인전의 명령과 판정&quot;">​</a></h3><p>일반 이동 공격의 입력은 <strong>이동 위치 → 방향 → 사거리 내 대상 공격</strong>이다. 상대의 이동 이후 거리와 방향이 공격 성립에 중요하며, 제자리에서는 방어·비기·도주를 고를 수 있다. 실제 타일 크기·행동 동시 처리의 세부 우선순위·명중 난수 공식은 이번 공식 문서로 확정하지 않는다. [문서][미확인][S-TR-M3500]</p><table tabindex="0"><thead><tr><th>무기</th><th>대응 기능</th><th>거리·행동 특징</th></tr></thead><tbody><tr><td>도검</td><td>무예</td><td>단거리, 비기 종류가 많음</td></tr><tr><td>창</td><td>무예</td><td>바로 근접한 상대를 때릴 수 없어 간격 유지 필요</td></tr><tr><td>쿠나이</td><td>인술</td><td>근거리~원거리, 기본 위력이 낮음</td></tr><tr><td>사슬낫</td><td>인술</td><td>근거리~중거리</td></tr><tr><td>활</td><td>궁술</td><td>장거리, 발사 후 잠시 행동 제한</td></tr><tr><td>화승총</td><td>철포</td><td>강한 장거리, 발사 후 잠시 행동 제한</td></tr></tbody></table><p>표 전체: [문서][S-TR-M3500]. 전투 도중 장비 교체는 불가능하다. 무력과 무구 가치가 공격·방어에, 무력이 이동 범위에 영향을 주지만 <code>무력 - 방어력 = 피해</code> 같은 단순 공식은 공개 근거가 없다. [문서][미확인][S-TR-M3500]</p><p><strong>기합의 확인된 규칙:</strong> 행동마다 <strong>+1</strong>, 피격 때 추가 <strong>+1</strong>, 방어 행동은 총 <strong>+2</strong>로 설명된다. 방어는 받는 피해를 <strong>절반</strong>으로 줄인다. 따라서 같은 공격의 미방어 피해가 40이라면 방어 피해는 약 <strong>20</strong>이며 정수 처리 방식은 미확인이다. 비기는 정해진 기합을 소모한다. [문서][S-TR-M3500]; [추론][미확인][S-TR-M3500]</p><table tabindex="0"><thead><tr><th>비기 예</th><th style="text-align:right;">소비 기합</th><th>효과</th></tr></thead><tbody><tr><td>철벽(鉄壁)</td><td style="text-align:right;">2</td><td>방어력 증가</td></tr><tr><td>상처약(傷薬)</td><td style="text-align:right;">2</td><td>자신/아군 체력 <strong>30</strong> 회복(한국어 카드 표)</td></tr><tr><td>지혈(止血)</td><td style="text-align:right;">4</td><td>자신/아군 체력 <strong>60</strong> 회복(한국어 카드 표)</td></tr><tr><td>카스미(霞)</td><td style="text-align:right;">4</td><td>도검 공격과 행동불능 부여</td></tr><tr><td>마키야리(巻槍)</td><td style="text-align:right;">5</td><td>창으로 원형 궤도의 적들을 공격</td></tr><tr><td>마로바시(転)</td><td style="text-align:right;">8</td><td>신카게류의 필드 전체 공격(한국어 카드 표)</td></tr></tbody></table><p>표 전체: [문서][S-TR-M3500][S-TR-K02]. 카드 표의 ‘위력 120’ 등을 <strong>항상 HP 120 피해</strong>로 읽지 않는다. 내부 위력과 최종 피해는 다른 층이다. [추론][S-TR-K02][S-TR-M3500]</p><p>한국어 카드 자료에는 기성(気声) 성공률이 <code>(80 - 상대 기능×10)%</code>라고 제시된다. 해당 기능값이 4라는 가정이면 **40%**다. 그러나 무기별 ‘상대 기능’ 선택·범위 제한·반올림은 직접 검증하지 못했으므로 이는 <strong>커뮤니티 보고 공식</strong>이지 역설계로 확정한 공통 명중식이 아니다. [문서][추론][미확인][S-TR-K02]</p><p>승리는 기본적으로 적 전원 격파, 패배는 자신 또는 보호 대상의 격파, 도주 성공은 무승부다. 도주 가능성은 무력이 높고 적에서 멀수록 유리하다. [문서][S-TR-M3500]</p><h3 id="_6-2-합전-편성과-9개-병종-dx-기준" tabindex="-1">6.2 합전 편성과 9개 병종: DX 기준 <a class="header-anchor" href="#_6-2-합전-편성과-9개-병종-dx-기준" aria-label="Permalink to &quot;6.2 합전 편성과 9개 병종: DX 기준&quot;">​</a></h3><p>군단장은 자신을 포함한 <strong>최대 5개 부대</strong>를 지휘한다. 주인공이 군단장이 아니면 <strong>자신의 부대만</strong> 조작한다. 아래 이동력은 야전의 기본값이며 지형 비용과 스킬로 실제 도달 범위가 달라진다. [문서][S-TR-M3600]</p><table tabindex="0"><thead><tr><th>세력·병종</th><th style="text-align:right;">이동력</th><th>편성 물자</th><th>특징</th></tr></thead><tbody><tr><td>무사: 아시가루</td><td style="text-align:right;">4</td><td>별도 병기 불필요</td><td>근접·활 사격</td></tr><tr><td>무사: 기마</td><td style="text-align:right;">6</td><td>병사 1명당 군마 1</td><td>높은 공격·기동, 간접공격 불가</td></tr><tr><td>무사: 철포</td><td style="text-align:right;">3</td><td>병사 1명당 철포 1</td><td>강한 사격, 낮은 방어, 기본적으로 비·눈에 사격 불가</td></tr><tr><td>무사: 대통</td><td style="text-align:right;">3</td><td>대통 1문당 병사 10</td><td>강한 포격, 낮은 이동·방어</td></tr><tr><td>무사: 기마철포</td><td style="text-align:right;">6</td><td>병사 1명당 군마 1 + 철포 1</td><td>조건부 편성, 기병과 총병 결합</td></tr><tr><td>닌자: 닌자</td><td style="text-align:right;">5</td><td>별도 병기 불필요</td><td>닌자의 단일 병종, 활 사격 가능</td></tr><tr><td>해적: 세키부네(関船)</td><td style="text-align:right;">4</td><td>1척당 병사 10</td><td>기본 함선, 활 사격</td></tr><tr><td>해적: 대형선</td><td style="text-align:right;">5</td><td>1척당 병사 100</td><td>철포 사격</td></tr><tr><td>해적: 철갑선</td><td style="text-align:right;">6</td><td>1척당 병사 100</td><td>대통 포격</td></tr></tbody></table><p>표 전체: [문서][S-TR-M3600]. 예컨대 가로의 부대 4,000명을 기마철포로 만들려면 군마 <strong>4,000 + 철포 4,000</strong>이 필요하고, 4,000명 대통대라면 대통 <strong>400문</strong>이 필요하다. 특수 병종 해금은 별도다. [추론][S-TR-M4200][S-TR-M3600]</p><h3 id="_6-3-야전-지형-사기-지휘부" tabindex="-1">6.3 야전: 지형, 사기, 지휘부 <a class="header-anchor" href="#_6-3-야전-지형-사기-지휘부" aria-label="Permalink to &quot;6.3 야전: 지형, 사기, 지휘부&quot;">​</a></h3><ul><li>지도에서 적 군단과 조우하면 해당 위치에 따른 지형으로 야전이 열린다. 부대별로 이동하고, 이동 전후 특기·방책 등의 명령을 사용하며 공격할 수 있다. <strong>지형마다 이동력 소비와 전투력 변화가 다르며 UI에서 확인</strong>한다. [문서][S-TR-M3600]</li><li>병사 <strong>0 → 궤멸</strong>, 사기 <strong>0 → 퇴각</strong>. 적 군단장 부대가 궤멸하거나 퇴각하면 승리한다. 따라서 모든 적 병사를 죽일 필요는 없다. 군량수송 원군은 성 인접 칸에 도착하는 별도 목표가 있다. [문서][S-TR-M3600]</li><li>명령: 특기, 방책 설치, 복병 해제, 위임/해제, 대기, 퇴각. 퇴각은 지도 가장자리의 퇴각 지점에서 가능하다. 이동하지 않고 대기하면 이동력이 증가한다. [문서][S-TR-M3600]</li><li>혼란·착란·도발 중에는 조작 불가이며, 착란 부대는 아군을 공격할 수 있다. 날씨는 총병 운용에 직접 개입한다. 카드로 얻는 예외와 기본 날씨 규칙을 분리한다. [문서][S-TR-M3600][S-TR-K02]</li></ul><p><strong>중요 판본 차이:</strong> 2004 Windows 합전 카드는 한국어 자료상 <strong>사용 횟수 제한</strong> 방식이다. 콘솔/DX는 <strong>특기 포인트 소비</strong>, 행동 종료 때 <strong>1 회복</strong>, 최대 <strong>10</strong> 방식이다. 따라서 DX의 자원식을 원작에 적용하지 않는다. [문서][S-TR-K02][S-TR-M3600]</p><p>DX의 간단한 부대 자원식은 <code>다음 특기 = min(10, 현재 특기 - 소비량 + 행동 종료 회복 1)</code>로 재구성할 수 있다. 추가 회복 카드·특수 처리는 제외한 설명식이다. [추론][S-TR-K02][S-TR-M3600]</p><h3 id="_6-4-공성전-성문-군의-협상" tabindex="-1">6.4 공성전: 성문, 군의, 협상 <a class="header-anchor" href="#_6-4-공성전-성문-군의-협상" aria-label="Permalink to &quot;6.4 공성전: 성문, 군의, 협상&quot;">​</a></h3><p>군의에서 부대 배치·교섭·원군을 정한 뒤 각 부대가 순서대로 행동한다. 공격은 성문 <strong>강습</strong>, 사격, 포격, 특기, 다른 공격구로 이동; 수비는 <strong>사수</strong>와 방어 특기를 쓴다. 성문 내구가 0이 되면 다음 구역으로 진행하며 <strong>혼마루 성문 파괴</strong>도 공격 측 승리 조건이다. 뒷문 배치는 닌자·해적만 가능하다. [문서][S-TR-M3600]</p><p>원군 요청은 <strong>하루 1회</strong>, 다른 세력에는 사례금이 필요하다. <strong>1세력당 1군단, 최대 3군단</strong>을 요청할 수 있다. 교섭도 <strong>하루 1회</strong>이며, 공성전은 끝까지 부수는 것 외에 항복·퇴거·종속·물자 교환·휴전으로 종료할 수 있다. [문서][S-TR-M3600]</p><p><strong>협상 판정의 방향:</strong> 아군 전황이 유리할수록, 사자의 지모·변설이 높을수록 유리하다. 요구를 추가하면 교섭값이 증가하고, 최종 교섭값이 전황 막대 길이보다 작으면 성공 가능성이 높다. 이것은 <strong>보장 성공 부등식이 아니라 가능성 설명</strong>이며 정확한 확률 함수는 미확인이다. [문서][미확인][S-TR-M3600]</p><h2 id="_7-지도-세계-—-이동하는-개인과-흐르는-달력" tabindex="-1">7. 지도/세계 — 이동하는 개인과 흐르는 달력 <a class="header-anchor" href="#_7-지도-세계-—-이동하는-개인과-흐르는-달력" aria-label="Permalink to &quot;7. 지도/세계 — 이동하는 개인과 흐르는 달력&quot;">​</a></h2><h3 id="_7-1-지도-규모와-화면-층" tabindex="-1">7.1 지도 규모와 화면 층 <a class="header-anchor" href="#_7-1-지도-규모와-화면-층" aria-label="Permalink to &quot;7.1 지도 규모와 화면 층&quot;">​</a></h3><table tabindex="0"><thead><tr><th>층·수량</th><th>기능</th><th>근거</th></tr></thead><tbody><tr><td>거점 <strong>4종</strong></td><td>성·마을·닌자 마을·해적 요새</td><td>[문서][S-TR-M3100]</td></tr><tr><td>성 <strong>180개</strong></td><td>무사 지배·전쟁의 주요 대상</td><td>[문서][S-TR-M4200]</td></tr><tr><td>닌자 마을 <strong>12개</strong></td><td>닌자 세력과 지역 전수 체계</td><td>[문서][S-TR-M4300]</td></tr><tr><td>해역 <strong>16개</strong></td><td>해적 지배 목표</td><td>[문서][S-TR-M4400]</td></tr><tr><td>상업권 <strong>15개: DX 공식값</strong></td><td>도시·상인사 경쟁 단위</td><td>[문서][S-TR-M4500]</td></tr><tr><td>명소 카드 <strong>32곳: 한국어 목록</strong></td><td>탐방·명상·인물 이벤트</td><td>[문서][S-TR-K02]</td></tr><tr><td>해외 교역 도시 <strong>4곳</strong></td><td>나하·부산·닝보·루손</td><td>[문서][S-TR-K01][S-TR-K02]</td></tr></tbody></table><p>전국 이동 화면 → 거점의 시설 목록 → 시설 안 인물·행동 → 별도 개인전/합전 화면으로 전환한다. 이동 화면에는 날짜·현재 위치·목적지·주명·일자리 관련 이동 명령이 있고, 사람과 만나 대화하거나 장소에서 채집·명상·일수 지정 대기가 가능하다. 전국지도 km², 좌표 해상도, 모든 마을의 총수는 이번 근거로 확정하지 않는다. [문서][미확인][S-TR-M3100]</p><h3 id="_7-2-이동과-해외" tabindex="-1">7.2 이동과 해외 <a class="header-anchor" href="#_7-2-이동과-해외" aria-label="Permalink to &quot;7.2 이동과 해외&quot;">​</a></h3><p>이동 중에는 사람·도적·군단을 만날 수 있다. 일부 명마는 지도 이동속도를 높이고, 명소 카드의 산·폭포·사찰에서 명상할 수 있다. 단순한 인접 도시 클릭 순간이동이 아니라 <strong>임무 귀환·회복·수련과 날짜를 공유하는 이동</strong>이다. [문서][S-TR-M3100][S-TR-M3200][S-TR-M3400]; [추론][S-TR-M5100]</p><p>한국어 자료는 해외무역을 상인·해적의 경로로 설명한다. 나하 외 <strong>3곳</strong>은 외교문서가 필요하고, 관련 상인·해적 두령·지원 다이묘가 문서를 가지고 있으면 접근 조건에 활용된다. 해적의 해외 항해에는 <strong>대형선 50척 이상</strong>이 요구된다. 해외 교역을 곧 해외 영토 정복 시스템으로 해석하지 않는다. [문서][S-TR-K01]</p><h3 id="_7-3-일·월·년의-서로-다른-주기" tabindex="-1">7.3 일·월·년의 서로 다른 주기 <a class="header-anchor" href="#_7-3-일·월·년의-서로-다른-주기" aria-label="Permalink to &quot;7.3 일·월·년의 서로 다른 주기&quot;">​</a></h3><table tabindex="0"><thead><tr><th>시간 규칙</th><th>실제 작동</th></tr></thead><tbody><tr><td>일 단위 행동</td><td>이동·숙박·작업·대기 등이 날짜를 소비. 주명은 완료뿐 아니라 복귀·보고 기한 관리가 필요</td></tr><tr><td>매월 1일</td><td>소속자의 봉록이 자택 금고에 입금. 상인 판로의 월간 수익 보고</td></tr><tr><td>홀수 달 1~5일</td><td>하급 무사의 정기 평정. 놓치면 다음 평정까지 주명 수령 불가·공훈 손실</td></tr><tr><td>홀수 달 초</td><td>상인의 정기 평정</td></tr><tr><td>비정기 소집 후 1개월 이내</td><td>닌자·해적의 평정 참석. 닌자는 주명을 선택할 수 없음</td></tr><tr><td>상대별 매월</td><td>선물 1회, 다석 1회. 유파 비기 전수도 한국어 자료상 월 1회</td></tr><tr><td>매년 6월</td><td>교토 천람시합: 한국어 공략의 연례 대회</td></tr><tr><td>매년 2월 10일</td><td>조건을 열면 교토 철포대회; 상위 <strong>4위 이내</strong> 입상이 야마시로전 획득과 연결</td></tr><tr><td>연말</td><td>상인 지배인의 최소 5,000관 상납</td></tr><tr><td>1621년 1월 1일</td><td>다른 종료를 보지 못한 경우 제한시간 엔딩</td></tr></tbody></table><p>표 전체: [문서][S-TR-M3100][S-TR-M4200][S-TR-M4500][S-TR-M5100][S-TR-M5200][S-TR-M5300][S-TR-M5400][S-TR-M1200][S-TR-K01][S-TR-K02]. 특정 연례 이벤트는 자격·전제 이벤트가 있어 날짜만 맞춘다고 항상 발생하지 않는다. [문서][S-TR-K02]</p><p>따라서 <strong>‘월 1턴, 행동 1회’ 게임이 아니다.</strong> 하급 무사 정기 평정은 한 해 <strong>6번</strong>이지만 그 사이에 여러 여행·수련·교유를 수행한다. 지휘자가 된 성주는 평정의 방에서 원할 때 회의를 열 수 있다. 현실 그레고리력의 월별 일수와 동일한지, 모든 작업의 하루 미만 시간 단위가 같은지는 미확인이다. [추론][S-TR-M5100][S-TR-M5130]; [미확인][S-TR-M3100]</p><h3 id="_7-4-시나리오의-시간-창" tabindex="-1">7.4 시나리오의 시간 창 <a class="header-anchor" href="#_7-4-시나리오의-시간-창" aria-label="Permalink to &quot;7.4 시나리오의 시간 창&quot;">​</a></h3><p>원작·이식·DX를 합친 시나리오 연대는 <strong>1549, 1554, 1560, 1568, 1575, 1582, 1598</strong> 및 가상 1560 몽환이다. <strong>1584 나니와의 장은 DX 추가</strong>, DX는 총 <strong>9개</strong>다. 1560 일륜이 초기 시나리오이며 추가 시나리오는 카드·클리어 조건으로 열린다. 해금 장수는 판본마다 다르므로 하나의 공통 표로 합치지 않는다. [문서][S-TR-K01][S-TR-O03]</p><p>시작 연대에 따라 스승의 생존, 세력 규모, 역사적 인맥과 가능한 사건이 바뀐다. 이는 단지 지도의 색깔 변화가 아니라 <strong>배울 기술·만날 사람·남은 생애의 변화</strong>다. [추론][S-TR-K01][S-TR-M3500]</p><h2 id="_8-외교-세력-—-네-조직과-성주의-통치" tabindex="-1">8. 외교/세력 — 네 조직과 성주의 통치 <a class="header-anchor" href="#_8-외교-세력-—-네-조직과-성주의-통치" aria-label="Permalink to &quot;8. 외교/세력 — 네 조직과 성주의 통치&quot;">​</a></h2><h3 id="_8-1-관계의-층" tabindex="-1">8.1 관계의 층 <a class="header-anchor" href="#_8-1-관계의-층" aria-label="Permalink to &quot;8.1 관계의 층&quot;">​</a></h3><p><strong>개인 친밀도, 세력 외교감정, 조정 공헌, 주군에 대한 공훈, 상인의 다이묘 기여도</strong>는 서로 다른 목적의 값이다. 친한 다이묘 한 명이 있다고 자동 동맹·관위·어용상인 지위가 모두 생기는 것은 아니다. [추론][S-TR-M3200][S-TR-M3600][S-TR-M4500][S-TR-M5160]</p><ul><li>무사는 다른 가문의 성을, 닌자·해적은 같은 종류 조직의 거점 또는 다이묘 성을 공격할 수 있다. <strong>동맹 세력은 공격 목표로 선택 불가</strong>다. [문서][S-TR-M3600]</li><li>닌자·해적은 지지 다이묘를 선택하고 지원한다. 한국어 자료는 이들이 함락한 다이묘 성의 귀속이 지원 가문으로 넘어간다고 설명한다. 닌자 마을과 해적 요새의 독자 지배와 구별한다. [문서][S-TR-M5200][S-TR-M5300][S-TR-K01]</li><li>어용상인은 다이묘에게 전략을 진언할 수 있다. 당주가 해당 가문의 <strong>가로 이상</strong>과 교유하여 중개역을 얻는 것이 진입 경로다. 상인사 경쟁에는 유력 다이묘의 어용상인 지위와 경쟁 어용상인보다 높은 기여도가 필요하다. [문서][S-TR-M4500]</li></ul><h3 id="_8-2-전쟁-명분과-휴전" tabindex="-1">8.2 전쟁 명분과 휴전 <a class="header-anchor" href="#_8-2-전쟁-명분과-휴전" aria-label="Permalink to &quot;8.2 전쟁 명분과 휴전&quot;">​</a></h3><p>자기 또는 동맹 세력에 대한 공격, 상대의 동맹 파기·선전포고·항복 권고 등이 공격 명분을 만든다. 명분 없이 공격하면 악명이 올라간다. 공가를 통한 <strong>치벌윤지</strong>로 조정의 명분을 얻거나 <strong>칙명강화</strong>로 화해를 중재받을 수 있다. [문서][S-TR-M3600][S-TR-M5160]</p><p>공성 교섭에서는 성주 처단·전원 항복·성 밖 퇴거·종속·동맹 파기와 군자금·군량·말·총·대통·귀중품 양도를 협상한다. 휴전은 최대 <strong>60개월</strong>이다. 휴전 중 공격하면 악명 증가와 <strong>다른 모든 세력의 관계 악화</strong>가 따른다. [문서][S-TR-M3600]</p><h3 id="_8-3-성주·국주의-내정과-인사" tabindex="-1">8.3 성주·국주의 내정과 인사 <a class="header-anchor" href="#_8-3-성주·국주의-내정과-인사" aria-label="Permalink to &quot;8.3 성주·국주의 내정과 인사&quot;">​</a></h3><table tabindex="0"><thead><tr><th>관리 축</th><th>성주의 수단</th><th>담당자·자원 판단</th></tr></thead><tbody><tr><td>인재</td><td>낭인 권유, 부하 승진, 주명 배정</td><td>신분이 낮으면 맡길 수 있는 주명이 제한됨</td></tr><tr><td>재정</td><td>군자금 조달, 광산 개발</td><td>조달은 산술·변설 높은 부하가 유리</td></tr><tr><td>군비</td><td>징병·훈련, 군마·철포 확보</td><td>병사 수뿐 아니라 병종용 물자가 필요</td></tr><tr><td>토지·성곽</td><td>신전 개발, 보수·증축</td><td>개간·건축·광산 기능을 업무에 맞춤</td></tr><tr><td>원정</td><td>군단 편성, 공격 목표와 지휘</td><td>주군의 공략 명령과 현지 군량 관리</td></tr><tr><td>외교</td><td>친선·지배·원군 연결</td><td>닌자·해적과의 관계를 군사 지원으로 전환</td></tr><tr><td>복수 성</td><td>국주의 성간 물자 운송</td><td>주명 대상 성을 함락해야 자기 직할에 추가됨</td></tr></tbody></table><p>표 전체: [문서][S-TR-M5130][S-TR-M3300][S-TR-M3600]. 성주가 직접 일할 수도 있으므로 단순 자동 생산 건물 배치가 아니라 <strong>사람에게 예산과 시간을 배분하는 행정</strong>이다. 예를 들어 뛰어난 성주 본인이 군자금 조달을 맡으면 실적은 좋아질 수 있지만 같은 기간 외교·원정·사사를 포기하는 기회비용이 생긴다. [추론][S-TR-M5130]</p><p>다이묘는 세력이 커지면 가로 이상 부하를 성주·국주로 임명하고 지역을 맡길 수 있다. 전쟁 목표·동맹 선택·다른 조직에 의뢰·조정 교섭까지 스스로 정하므로 주군의 명령을 받던 시기의 제약과 책임이 뒤집힌다. [문서][S-TR-M5160]</p><h3 id="_8-4-통일은-반드시-모든-성의-직접-소유가-아니다" tabindex="-1">8.4 통일은 반드시 모든 성의 직접 소유가 아니다 <a class="header-anchor" href="#_8-4-통일은-반드시-모든-성의-직접-소유가-아니다" aria-label="Permalink to &quot;8.4 통일은 반드시 모든 성의 직접 소유가 아니다&quot;">​</a></h3><p>DX 공식의 무사 최고 목표는 <strong>전국 180성 지배</strong>, <strong>소속 가문과 동맹 가문의 전국 180성 지배</strong>, 또는 소속/자기 다이묘의 <strong>정1위</strong>다. 한국어 위키는 관위 경로에 지배력 <strong>36,000 이상</strong> 등을 추가로 설명한다. 이 값은 공훈과 다른 <strong>가문 지배력</strong>이며, 공식 요약만으로 모든 세부 엔딩 분기를 대체하지 않는다. [문서][S-TR-M4200][S-TR-K01]</p><h2 id="_9-이벤트-내러티브-—-역사-개인적-선택-직업의-결말" tabindex="-1">9. 이벤트/내러티브 — 역사, 개인적 선택, 직업의 결말 <a class="header-anchor" href="#_9-이벤트-내러티브-—-역사-개인적-선택-직업의-결말" aria-label="Permalink to &quot;9. 이벤트/내러티브 — 역사, 개인적 선택, 직업의 결말&quot;">​</a></h2><h3 id="_9-1-역사적-사건과-개인-시점" tabindex="-1">9.1 역사적 사건과 개인 시점 <a class="header-anchor" href="#_9-1-역사적-사건과-개인-시점" aria-label="Permalink to &quot;9.1 역사적 사건과 개인 시점&quot;">​</a></h3><p>역사 이벤트는 단순 날짜 알림만이 아니다. 참가 인물·소속·전쟁 결과에 따라 플레이어가 당사자가 되거나 전령을 통해 타인의 사건을 듣는다. 중요한 인물의 생사와 성의 귀속이 바뀌면 이후 개인적 목표의 조건도 바뀐다. 이벤트 엔진의 정확한 내부 평가 순서·모든 조건식은 미확인이다. [문서][추론][미확인][S-TR-K01]</p><table tabindex="0"><thead><tr><th>예</th><th>선택·분기</th><th>결과의 종류</th></tr></thead><tbody><tr><td>나가시노</td><td>다케다 가쓰요리로 오다·도쿠가와 연합군 격파</td><td>노부나가·이에야스 전사라는 역사 IF</td></tr><tr><td>세키가하라</td><td>서군 승리</td><td>후속 후지카와 전투, 승리 시 이에야스 전사</td></tr><tr><td>히데요시의 모반</td><td>혼노지 전후 전제에 가까운 조건에서 별도 모반 경로</td><td>미쓰히데 동조·노부나가와 충돌 등 개인 전용 분기</td></tr><tr><td>고사쿠의 교역 의뢰</td><td>닭새우 → 비젠야키 → 스시 → 유리</td><td>투자·판로·해외교역을 배우는 단계별 의뢰와 보수·공훈</td></tr><tr><td>의술의 외국인 사건</td><td>곤경의 명나라 사람을 돕고 조합법 제안 수락</td><td>조합 미니게임 <strong>3연속 성공</strong>으로 만능약 제조 해금</td></tr></tbody></table><p>표 전체: [문서][S-TR-K01][S-TR-K02][S-TR-K03]. 표는 사건의 대표 결과이며 정확한 연도·성·생존자 전체 조건을 생략한 <strong>요약</strong>이다. 날짜 하나만으로 재현 가능한 공략으로 사용하지 않는다. [미확인][S-TR-K01]</p><h3 id="_9-2-직업별-엔딩-목표의-구체-예" tabindex="-1">9.2 직업별 엔딩 목표의 구체 예 <a class="header-anchor" href="#_9-2-직업별-엔딩-목표의-구체-예" aria-label="Permalink to &quot;9.2 직업별 엔딩 목표의 구체 예&quot;">​</a></h3><table tabindex="0"><thead><tr><th>계열</th><th>수치가 있는 대표 조건·목표</th><th>근거</th></tr></thead><tbody><tr><td>검호</td><td>직접 제자 <strong>20명</strong>, 또는 도장 문하생 <strong>10,000명</strong>, 또는 천람대회 우승 등</td><td>[문서][S-TR-M5500]</td></tr><tr><td>상인</td><td>DX 공식 <strong>15개 상업권</strong> 상인사, 또는 전 다이묘 어용상인, 또는 지지 다이묘 통일</td><td>[문서][S-TR-M4500]</td></tr><tr><td>닌자</td><td><strong>12개</strong> 마을 지배 또는 전 지역 인술 습득 등</td><td>[문서][S-TR-M4300]</td></tr><tr><td>해적</td><td><strong>16개</strong> 해역 지배 또는 지지 다이묘 통일</td><td>[문서][S-TR-M4400]</td></tr><tr><td>다인: 조정의 다두</td><td>한국어 공략상 다성, 다석 <strong>800회 이상</strong>, 다기 제작 경험 <strong>400 이상</strong>, 방문 제안 수락</td><td>[문서][S-TR-K01]</td></tr><tr><td>의사: 의료학교</td><td>한국어 공략상 의사명성 <strong>3,000 이상</strong>, 정확한 무료진료 <strong>100회</strong>, 해당 약조합 <strong>100일</strong>, 총소지금 <strong>10,000관 이상</strong></td><td>[문서][S-TR-K01]</td></tr><tr><td>대장장이</td><td>고급 제작법을 익혀 가치 <strong>7</strong> 무구 제작 후 관련 헌상 이벤트</td><td>[문서][S-TR-K01]</td></tr></tbody></table><p>구도 직업은 목표를 달성했을 때 엔딩을 선택하지 않고 활동을 계속할 수 있는 경우가 있다. 반대로 특정 세력 제패는 즉시 종결되므로 다른 카드 수집을 마치기 전에 최종 거점을 함락하면 목표가 막힐 수 있다. <strong>전 엔딩이 동일한 ‘클리어 후 자유플레이’를 보장하지 않는다.</strong> [문서][S-TR-K01]</p><h3 id="_9-3-같은-통일도-다른-후일담" tabindex="-1">9.3 같은 통일도 다른 후일담 <a class="header-anchor" href="#_9-3-같은-통일도-다른-후일담" aria-label="Permalink to &quot;9.3 같은 통일도 다른 후일담&quot;">​</a></h3><p>한국어 공략은 완전 통일의 ‘300년 태평’ 조건에 다이묘 본거지 주민안정도 <strong>75 이상</strong>, 잇키 발생지 <strong>1곳 이하</strong>, 다이묘 악명 <strong>60 미만</strong>, 악명 카드 <strong>0개</strong>를 든다. 통일 여부만 아니라 안정·악명·경제 상황이 정권의 장기적 후일담을 바꾼다는 예다. 이 문턱들은 커뮤니티의 엔딩 조건 정리이며 모든 판본에서 실행 검증된 식은 아니다. [문서][S-TR-K01]</p><p>DX 공식은 원작·이식판 기반에 <strong>엔딩 5종 추가, 총 39종</strong>, <strong>이벤트 20종 이상 추가, 총 630개 이상</strong>이라고 설명한다. 새 엔딩 목록·자동 저장도 제공한다. 개인적 사건을 대폭 추가하는 Windows 이벤트 편집 기능은 공식적으로 존재하지만 <strong>사용자 제작 이벤트·모드의 규칙은 본 문서 범위 밖</strong>이다. [문서][S-TR-O01][S-TR-O03]</p><h2 id="_10-난이도-압박-—-생존보다-제한된-생애의-선택" tabindex="-1">10. 난이도/압박 — 생존보다 ‘제한된 생애의 선택’ <a class="header-anchor" href="#_10-난이도-압박-—-생존보다-제한된-생애의-선택" aria-label="Permalink to &quot;10. 난이도/압박 — 생존보다 ‘제한된 생애의 선택’&quot;">​</a></h2><h3 id="_10-1-압박과-완화-수단" tabindex="-1">10.1 압박과 완화 수단 <a class="header-anchor" href="#_10-1-압박과-완화-수단" aria-label="Permalink to &quot;10.1 압박과 완화 수단&quot;">​</a></h3><table tabindex="0"><thead><tr><th>압박</th><th>실패가 생기는 방식</th><th>완화 수단</th></tr></thead><tbody><tr><td>일정</td><td>홀수 달 평정 누락, 주명 보고 지연, 연례 대회 놓침</td><td>왕복 일정 확보, 다음 평정 표시 확인</td></tr><tr><td>체력·질병</td><td>낮은 체력으로 발병, 능력 <strong>1/2</strong>, 기능 <strong>-1</strong>, 수련 불가</td><td>자택 휴식, 숙박, 약, 의사 치료</td></tr><tr><td>현금·적재 위험</td><td>대량 교역품 소지 시 도적 조우 위험, 패배하면 현금·교역품 상실</td><td>용심봉·무예·좋은 장비, 일부 재산을 주고 통과</td></tr><tr><td>전쟁</td><td>병사 <strong>0</strong> 궤멸, 사기 <strong>0</strong> 퇴각, 군량 고갈의 사기 급락</td><td>물자 편성, 보급 원군, 교섭·퇴각</td></tr><tr><td>출세 정체</td><td>약한 주군·임명 여건·배신 신분의 승진 한계</td><td>인맥·실적·이직 또는 독립, 단 배신 위험 존재</td></tr><tr><td>조직 의무</td><td>닌자의 강제 주명, 탈주 후 추격, 지배인 연말 <strong>5,000관</strong></td><td>다양한 기능과 체력 준비, 소속 선택의 신중함</td></tr><tr><td>도덕적·사회적 결과</td><td>악명·명분 없는 전쟁·악명 카드가 외교와 후일담에 영향</td><td>명분 확보, 합의 이행, 시주 등</td></tr><tr><td>수명·역사</td><td>스승·후원자 사망, 역사 이벤트로 세력 변동, <strong>1621-01-01</strong> 종결</td><td>필요한 전수·교유·목표를 생애 안에 우선 배치</td></tr></tbody></table><p>표 전체: [문서][S-TR-M1200][S-TR-M3100][S-TR-M3300][S-TR-M3500][S-TR-M3600][S-TR-M5100][S-TR-M5400][S-TR-K01].</p><h3 id="_10-2-실패·패배·게임-종료를-구분한다" tabindex="-1">10.2 실패·패배·게임 종료를 구분한다 <a class="header-anchor" href="#_10-2-실패·패배·게임-종료를-구분한다" aria-label="Permalink to &quot;10.2 실패·패배·게임 종료를 구분한다&quot;">​</a></h3><ul><li><strong>임무 실패:</strong> 공훈 손실·승진 지연이 가능하지만 즉시 게임오버가 아니다. 닌자도 성공·실패 모두 상사에게 보고해야 한다. [문서][S-TR-M1200][S-TR-M5200]</li><li><strong>개인전 패배:</strong> 대련 패배, 도적에게 재산 강탈, 호위 실패 등 전투 맥락별로 결과가 다르다. ‘HP 0 = 영구 사망’으로 통일하면 틀린다. [문서][S-TR-M1200][S-TR-M3500]</li><li><strong>합전 손실:</strong> 자기 부대가 도중에 궤멸하면 전공이 <strong>절반</strong>이 된다. 병력·거점 손실과 개인 생애 종료는 별도다. [문서][S-TR-M5100]</li><li><strong>치명적 사건:</strong> 처단·특정 악행 관련 개인전 등 죽음으로 끝나는 경로가 있다. 사망 확률·무기별 처형 확률의 공통식은 미확인이다. [문서][미확인][S-TR-M3600][S-TR-K01]</li><li><strong>수명 종료:</strong> 각 인물에게 설정된 수명이 끝나면 엔딩 조건이 된다. 모든 인물이 같은 나이까지 살거나 회복약으로 시간 제한 자체가 사라진다고 보장하지 않는다. [문서][S-TR-M1200]</li><li><strong>강제 은거:</strong> 다이묘가 가신단에게 유폐된 뒤 게임 종료를 선택하는 경로가 있다. [문서][S-TR-M1200]</li><li><strong>타 세력 통일:</strong> 기능 수준이 낮은 낭인은 다른 다이묘의 통일로 별도 종료를 맞을 수 있다. 조직 밖에 산다고 세계 진행에서 완전히 분리되는 것은 아니다. [문서][S-TR-M1200]</li><li><strong>최종 시한:</strong> 다른 엔딩 없이 <strong>1621년 1월 1일</strong>에 도달하면 제한시간 엔딩이다. 이 시한과 주인공 개인 수명은 별도 제약이다. [문서][S-TR-M1200]</li></ul><h3 id="_10-3-난이도-곡선의-성격" tabindex="-1">10.3 난이도 곡선의 성격 <a class="header-anchor" href="#_10-3-난이도-곡선의-성격" aria-label="Permalink to &quot;10.3 난이도 곡선의 성격&quot;">​</a></h3><p>초반에는 빈약한 봉록과 체력, 낮은 기능, 인맥 부족이 겹친다. 돈과 좋은 장비·회복 비기·전군 강화 카드를 확보하면 위험이 크게 줄 수 있으나, 천람대회의 유명 검호나 특정 전수 조건은 별도의 장벽으로 남는다. 후기 난이도는 단순히 적 HP가 늘어나는 곡선이 아니라 <strong>일정·역사 조건·권한·소속·수명·엔딩의 조합</strong>에서 나온다. 이는 공식 루프와 한국어 공략을 종합한 해석이며 AI 강도와 난이도 배율을 수치로 측정한 결과는 아니다. [추론][S-TR-M1200][S-TR-M5100][S-TR-K01]</p><p>미니게임은 환경설정으로 생략 가능하지만 직접 수행의 고득점 기회를 포기할 수 있다. DX 자동저장은 편의 기능이지 게임 내 불이익이나 위험의 삭제가 아니다. 전투 피해 공식, 행동별 기능 XP, 친밀도 내부식, 세금·수확의 월별 전체 식, 모든 이벤트 조건은 <strong>미확인 영역</strong>으로 남긴다. 공식 수치·한국어 공략 보고·설명용 계산을 섞어 구현 명세처럼 인용하지 않는 것이 이 참고서의 사용 원칙이다. [문서][S-TR-M1200][S-TR-O03]; [미확인][S-TR-X01]</p><hr><h3 id="출처와-조사-범위" tabindex="-1">출처와 조사 범위 <a class="header-anchor" href="#출처와-조사-범위" aria-label="Permalink to &quot;출처와 조사 범위&quot;">​</a></h3><p>조회일: <strong>2026-09-06</strong>. 검색 결과와 AI 브리핑은 원문 발견에만 사용했고 게임 사실의 근거로 인용하지 않았다. 한국어 위키 본문 3건, 공식 DX 웹 매뉴얼 21쪽, 공식 소개·신요소 페이지, Steam 상점 본문을 사용했다. 일부 404/403 응답은 근거에서 제외했다. 원문·정제 텍스트·조회 로그는 <code>.omo/evidence/gameplay-rubric-6d3fe97/ui-reference/tr-raw/</code>에 보존했다. 게임 실행·메모리 분석·소스 역설계는 수행하지 않았다.</p><table tabindex="0"><thead><tr><th>ID</th><th>출처</th><th>사용 범위·한계</th></tr></thead><tbody><tr><td>S-TR-K01</td><td><a href="https://namu.wiki/w/%ED%83%9C%ED%95%A9%EC%9E%85%EC%A7%80%EC%A0%84%205" target="_blank" rel="noreferrer">나무위키: 태합입지전 5</a></td><td>한국어 종합 공략. 원작·이식·DX 혼재; 계급·상업권 일부가 공식과 상충</td></tr><tr><td>S-TR-K02</td><td><a href="https://namu.wiki/w/%ED%83%9C%ED%95%A9%EC%9E%85%EC%A7%80%EC%A0%84%205/%EC%B9%B4%EB%93%9C" target="_blank" rel="noreferrer">나무위키: 태합입지전 5/카드</a></td><td>칭호·비기·합전·명소·판본 차이. 최종 피해/확률을 직접 검증한 것은 아님</td></tr><tr><td>S-TR-K03</td><td><a href="https://namu.wiki/w/%ED%83%9C%ED%95%A9%EC%9E%85%EC%A7%80%EC%A0%84%205/%EA%B5%90%EC%97%AD%ED%92%88" target="_blank" rel="noreferrer">나무위키: 태합입지전 5/교역품</a></td><td>중량·투자 규모·가공품·계절·필수품. 목록 일부 항목은 미완성</td></tr><tr><td>S-TR-O01</td><td><a href="https://www.gamecity.ne.jp/taikou5dx/" target="_blank" rel="noreferrer">공식 V DX 사이트</a></td><td>리코에이션, 직업, 플랫폼, 인물·편집 기능</td></tr><tr><td>S-TR-O02</td><td><a href="https://store.steampowered.com/app/1842810/" target="_blank" rel="noreferrer">Steam: Taiko Risshiden V DX</a></td><td>개발·배급·직업·지역별 출시일 표시</td></tr><tr><td>S-TR-O03</td><td><a href="https://www.gamecity.ne.jp/taikou5dx/features.html" target="_blank" rel="noreferrer">공식: 신요소</a></td><td>DX 960명·9시나리오·39엔딩·630+이벤트 등</td></tr><tr><td>S-TR-M1200</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/1200.html" target="_blank" rel="noreferrer">공식 매뉴얼: 게임의 흐름</a></td><td>직업 분류·주명·성장·카드·수명·종결 조건</td></tr><tr><td>S-TR-M3100</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/3100.html" target="_blank" rel="noreferrer">공식 매뉴얼: 화면</a></td><td>4종 거점·체력·이동·채집</td></tr><tr><td>S-TR-M3200</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/3200.html" target="_blank" rel="noreferrer">공식 매뉴얼: 마을 활동</a></td><td>시설·관계 월간 제한·의뢰·경제·아이템</td></tr><tr><td>S-TR-M3300</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/3300.html" target="_blank" rel="noreferrer">공식 매뉴얼: 능력과 기능</a></td><td>5능력·16기능·사사 자격·질병·단련</td></tr><tr><td>S-TR-M3400</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/3400.html" target="_blank" rel="noreferrer">공식 매뉴얼: 카드</a></td><td>6종·세이브 등록·회차 효력</td></tr><tr><td>S-TR-M3500</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/3500.html" target="_blank" rel="noreferrer">공식 매뉴얼: 개인전</a></td><td>명령·기합·방어·6무기·비기·승패</td></tr><tr><td>S-TR-M3600</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/3600.html" target="_blank" rel="noreferrer">공식 매뉴얼: 합전</a></td><td>명분·9병종·야전·공성·사기·포인트·원군·교섭</td></tr><tr><td>S-TR-M4200</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/4200.html" target="_blank" rel="noreferrer">공식 매뉴얼: 무사</a></td><td>180성·승진 공훈·월급·지휘병력</td></tr><tr><td>S-TR-M4300</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/4300.html" target="_blank" rel="noreferrer">공식 매뉴얼: 닌자</a></td><td>12마을·가입·DX 계급값</td></tr><tr><td>S-TR-M4400</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/4400.html" target="_blank" rel="noreferrer">공식 매뉴얼: 해적</a></td><td>16해역·가입·DX 계급값</td></tr><tr><td>S-TR-M4500</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/4500.html" target="_blank" rel="noreferrer">공식 매뉴얼: 상인</a></td><td>15상업권·급료·적재·판로·어용상인·1개월 경쟁</td></tr><tr><td>S-TR-M5100</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/5100.html" target="_blank" rel="noreferrer">공식 매뉴얼: 하급 무사 생활</a></td><td>평정·보고·배신·전공 반감</td></tr><tr><td>S-TR-M5130</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/5130.html" target="_blank" rel="noreferrer">공식 매뉴얼: 성주·국주 생활</a></td><td>인사·내정·군비·운송·공략명령</td></tr><tr><td>S-TR-M5160</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/5160.html" target="_blank" rel="noreferrer">공식 매뉴얼: 다이묘 생활</a></td><td>모반·상속·조정·관위·위임</td></tr><tr><td>S-TR-M5200</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/5200.html" target="_blank" rel="noreferrer">공식 매뉴얼: 닌자 생활</a></td><td>비정기 소집·강제 임무·독립</td></tr><tr><td>S-TR-M5300</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/5300.html" target="_blank" rel="noreferrer">공식 매뉴얼: 해적 생활</a></td><td>소집·수련·독립·두령 축출</td></tr><tr><td>S-TR-M5400</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/5400.html" target="_blank" rel="noreferrer">공식 매뉴얼: 상인 생활</a></td><td>평정·도적 위험·연말 5,000관·분가</td></tr><tr><td>S-TR-M5500</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/5500.html" target="_blank" rel="noreferrer">공식 매뉴얼: 검호 생활</a></td><td>사제·인가·도장 1,000관·20명/1만명 엔딩</td></tr><tr><td>S-TR-M5600</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/5600.html" target="_blank" rel="noreferrer">공식 매뉴얼: 다인 생활</a></td><td>다선·다실·2명 초대·제작</td></tr><tr><td>S-TR-M5700</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/5700.html" target="_blank" rel="noreferrer">공식 매뉴얼: 의사 생활</a></td><td>진료 카드·약초·조합·처방·평판</td></tr><tr><td>S-TR-M5800</td><td><a href="https://www.gamecity.ne.jp/manual/TaikeWqS/jp/5800.html" target="_blank" rel="noreferrer">공식 매뉴얼: 대장장이 생활</a></td><td>하급 실습·사철·철·제작·화약</td></tr><tr><td>S-TR-X01</td><td><a href="https://wikiwiki.jp/taikou5dx/%E5%86%85%E9%83%A8%E8%A8%88%E7%AE%97%E5%BC%8F" target="_blank" rel="noreferrer">wikiwiki: 내부 계산식</a></td><td><strong>403 접근 차단. 미열람.</strong> 한국어 카드 문서가 연결하는 기능 XP 상세 근거이나 숫자 출처로 사용하지 않음</td></tr></tbody></table>',134)])])}const R=r(n,[["render",o]]);export{T as __pageData,R as default};
